def choose_move(observation):
    x, y = observation['self_position']
    width, height = observation['grid_width'], observation['grid_height']
    def move_towards(tx, ty):
        dx = 0
        dy = 0
        if tx > x:
            dx = 1
        elif tx < x:
            dx = -1
        if ty > y:
            dy = 1
        elif ty < y:
            dy = -1
        return [dx, dy]
    targets = observation.get('resources', []) + observation.get('opponents', [])
    if targets:
        target = min(targets, key=lambda t: abs(t['x'] - x) + abs(t['y'] - y))
        dx, dy = move_towards(target['x'], target['y'])
        return [dx, dy]
    # Move towards center to stay active
    center_x = width // 2
    center_y = height // 2
    return move_towards(center_x, center_y)
